function PoolBar({ label, value, max, dangerous = false }: { label: string; value: number; max: number; dangerous?: boolean }) {
  const percent = Math.max(0, Math.min(100, (value / max) * 100));
  return <div className="pool" aria-label={`${label}: ${value} of ${max}`}><div className="pool__label"><span>{label}</span><strong>{value} / {max}</strong></div><div className="pool__track"><span className={dangerous ? "pool__fill pool__fill--danger" : "pool__fill"} style={{ width: `${percent}%` }} /></div></div>;
}

function WrestlerCard({ state, id }: { state: MatchState; id: WrestlerId }) {
  const definition = wrestlerDefinition(state, id);
  const runtime = state.wrestlers[id];
  const legal = state.teams[definition.teamId].legalInRingId === id;
  return <article className={`wrestler-card wrestler-card--${definition.teamId} ${legal ? "wrestler-card--legal" : ""}`} aria-label={`${definition.name} status`}>
    <div className="wrestler-card__eyebrow">{definition.teamId === "player" ? "PLAYER" : "CPU"} - {runtime.location.toUpperCase()} {legal ? "- LEGAL" : ""}</div>
    <h2>{definition.name}</h2><p className="epithet">{definition.epithet}</p>
    <div className="stat-grid"><span><small>AV</small><strong>{baseAv(definition.attributes) + runtime.matchAvModifier}</strong><em>base {baseAv(definition.attributes)}</em></span><span><small>DV</small><strong>{baseDv(definition.attributes) + runtime.matchDvModifier}</strong><em>base {baseDv(definition.attributes)}</em></span><span><small>BODY</small><strong>{body(definition)}</strong><em>{definition.weight} lb</em></span><span><small>PACE</small><strong>{movesPerMinute(definition)}</strong><em>moves/min</em></span></div>
    <PoolBar label="DAM PTS" value={runtime.currentDamage} max={startingDamage(definition)} dangerous={runtime.currentDamage === 0} /><PoolBar label="END" value={runtime.currentEndurance} max={startingEndurance(definition)} dangerous={runtime.currentEndurance <= 0} />
    <div className="status-row">{state.hold?.defenderId === id && <span className="status status--bad">HELD</span>}{state.hold?.holderId === id && <span className="status">HOLDING</span>}{runtime.location === "floor" && <span className="status status--bad">OUTSIDE / COUNTOUT</span>}{runtime.dodgingUntilTick > state.tick && <span className="status">DODGING</span>}{runtime.egotistPosing && <span className="status status--bad">POSING - OPPONENT +5 AV</span>}{runtime.stupidMovesActive && <span className="status status--bad">STUPID MOVES</span>}{runtime.charmRemaining > 0 && <span className="status">CHARM {runtime.charmRemaining}</span>}{runtime.injuryWeeks > 0 && <span className="status status--bad">INJURY {runtime.injuryWeeks}W</span>}</div>
  </article>;
}

function TeamColumn({ state, teamId }: { state: MatchState; teamId: TeamId }) { return <div className="team-column">{state.teams[teamId].members.map((id) => <WrestlerCard key={id} state={state} id={id} />)}</div>; }

function PhaseStrip({ state }: { state: MatchState }) {
  const player = state.teams.player.legalInRingId;
  const ai = state.teams.ai.legalInRingId;
  return <div className="phase-strip" aria-label={`Minute ${state.minute}, phase ${state.phase}`}>{Array.from({ length: 10 }, (_, index) => index + 1).map((phase) => { const playerActive = activePhases(state.roster[player]).includes(phase); const aiActive = activePhases(state.roster[ai]).includes(phase); return <div key={phase} className={`phase ${state.phase === phase ? "phase--current" : ""}`}><strong>{phase}</strong><span role="img" aria-label={playerActive ? `Player active in phase ${phase}` : `Player inactive in phase ${phase}`} className={playerActive ? "pip pip--player" : "pip"} /><span role="img" aria-label={aiActive ? `AI active in phase ${phase}` : `AI inactive in phase ${phase}`} className={aiActive ? "pip pip--ai" : "pip"} /></div>; })}</div>;
}

function actionFamily(action: LegalAction): string { const type = action.intent.type; if (type === "attack" || type === "irish-whip") return "attacks"; if (type === "recover") return "recovery"; if (["tag", "double-team", "distract-referee", "pin-interference", "enter-ring", "exit-ring"].includes(type)) return "team"; return "other"; }
function intentCharm(intent: Intent): number | null { if (intent.type === "attack" || intent.type === "irish-whip") return intent.attackCharm; if (["recover", "tag", "distract-referee", "pin-interference"].includes(intent.type)) return (intent as { charm: number }).charm; return null; }

function DecisionPanel({ state, onChoose, onStep }: { state: MatchState; onChoose: (intent: Intent) => void; onStep: () => void }) {
  const [search, setSearch] = useState(""); const [family, setFamily] = useState("all"); const [moveScope, setMoveScope] = useState<"prepared" | "all">("prepared"); const [charm, setCharm] = useState(0); const decision = state.decision;
  if (state.result) { const diceCount = state.events.reduce((total, event) => total + event.dice.length, 0); const winner = state.result.winnerId ? state.roster[state.result.winnerId]?.name : null; return <section className="decision decision--result" aria-live="polite"><div className="decision__kicker">MATCH COMPLETE</div><h2>{state.result.summary}</h2><p>{winner ? `Winner: ${winner}` : "Draw"} · Ending: {state.result.method.replaceAll("-", " ")}</p><div className="result-stats"><span><small>Match time</small><strong>{state.minute}:{state.phase.toString().padStart(2, "0")}</strong></span><span><small>Resolved events</small><strong>{state.events.length}</strong></span><span><small>Dice rolled</small><strong>{diceCount}</strong></span><span><small>Your decisions</small><strong>{state.inputLog.length}</strong></span></div></section>; }
  if (!decision) return <section className="decision decision--lab" aria-live="polite"><div className="decision__kicker">RULES LAB PAUSED</div><h2>Ready for the next deterministic transaction.</h2><button className="lab-step" onClick={onStep}>Step one transaction</button></section>;
  if (state.config.scenarioId && teamOf(state, decision.actorId) === "ai") return <section className="decision decision--lab" aria-live="polite"><div className="decision__kicker">AI DECISION QUEUED</div><h2>{decision.prompt}</h2><button className="lab-step" onClick={onStep}>Resolve one AI transaction</button></section>;
  const raw = decision.actions; const hasAttackList = raw.some((action) => action.intent.type === "attack" || action.intent.type === "irish-whip"); const hasCharmVariants = decision.kind !== "damage-charm" && raw.some((action) => (intentCharm(action.intent) ?? 0) > 0); const maxCharm = Math.max(0, ...raw.map((action) => intentCharm(action.intent) ?? 0));
  const actions = raw.filter((action) => { const actionCharm = intentCharm(action.intent); if (hasCharmVariants && actionCharm !== null && actionCharm !== charm) return false; if (family !== "all" && actionFamily(action) !== family) return false; if (moveScope === "prepared" && action.label.includes("(untrained)")) return false; const query = search.trim().toLowerCase(); return !query || `${action.label} ${action.detail}`.toLowerCase().includes(query); });
  const actorId = decision.actorId; const target = decision.kind === "pin-followup" || decision.kind === "knockout-pin" ? visiblePinTarget(state, actorId, false) : decision.kind === "submission-followup" ? visibleSubmissionTarget(state, actorId) : null;
  return <section className="decision" aria-labelledby="decision-title" aria-live="polite"><div className="decision__heading"><div><div className="decision__kicker">{decision.kind.replaceAll("-", " ")} - {state.roster[actorId].name}</div><h2 id="decision-title">{decision.prompt}</h2></div>{target !== null && <div className="target-box"><small>VISIBLE TARGET</small><strong>{target}</strong><span>on D20</span></div>}</div><div className="action-tools">{raw.length > 8 && <label>Find action<input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search maneuvers or rules" /></label>}{hasAttackList && <label>Move access<select value={moveScope} onChange={(event) => setMoveScope(event.target.value as "prepared" | "all")}><option value="prepared">Prepared moves</option><option value="all">Full catalog / untrained</option></select></label>}{raw.length > 8 && <label>Family<select value={family} onChange={(event) => setFamily(event.target.value)}><option value="all">All actions</option><option value="attacks">Attacks</option><option value="recovery">Recovery</option><option value="team">Team actions</option><option value="other">Follow-ups</option></select></label>}{hasCharmVariants && <label>Charm spend<select value={Math.min(charm, maxCharm)} onChange={(event) => setCharm(Number(event.target.value))}>{Array.from({ length: maxCharm + 1 }, (_, value) => <option key={value}>{value}</option>)}</select></label>}</div><div className="action-count">Showing {actions.length} of {raw.length} legal choices.</div><div className="action-grid">{actions.map((action) => <button key={action.key} className={action.intent.type.startsWith("decline") ? "action action--quiet" : "action"} onClick={() => { setSearch(""); onChoose(action.intent); }}><strong>{action.label}</strong><span>{action.detail}</span></button>)}</div>{actions.length === 0 && <p className="empty-filter">No legal actions match the current filters.</p>}</section>;
}

function EventLog({ state }: { state: MatchState }) { return <aside className="event-log" aria-label="Match log"><div className="panel-title"><span>MATCH LOG</span><small>{state.events.length} events</small></div><div className="sr-only" aria-live="polite" aria-atomic="true">{state.events.at(-1)?.summary ?? "No resolved events yet."}</div><ol>{[...state.events].reverse().slice(0, 24).map((event) => <li key={event.sequence}><details open={event.sequence === state.events.length}><summary><span>{event.minute}:{event.phase.toString().padStart(2, "0")}</span>{event.summary}</summary><div className="event-detail">{event.detail.map((line, index) => <p key={`${event.sequence}-${index}`}>{line}</p>)}{event.dice.length > 0 && <p className="dice-line">Dice: {event.dice.map((die) => `${die.label}: D${die.sides} ${die.result}`).join(" - ")}</p>}<details className="event-technical"><summary>Technical details</summary><code>{event.preStateHash} -&gt; {event.postStateHash}</code></details></div></details></li>)}</ol></aside>; }

interface RosterChoice { key: string; label: string; record?: WrestlerCareerRecord; officialId?: string; fixtureId?: string }
function rosterChoices(records: WrestlerCareerRecord[], includeFixtures = false): RosterChoice[] { const official = OFFICIAL_WRESTLER_PROFILES.map((profile) => ({ key: `official:${profile.id}`, label: `${officialDisplayName(profile)} (${profile.careerWp} WP)`, officialId: profile.id })); const custom = records.map((record) => ({ key: `record:${record.id}`, label: `${record.name} (${record.careerWp} WP)`, record })); const fixtures = includeFixtures ? Object.values(WRESTLERS).map((row) => ({ key: `fixture:${row.id}`, label: `${row.name} (test fixture)`, fixtureId: row.id })) : []; return [...official, ...custom, ...fixtures].sort((left, right) => left.label.localeCompare(right.label)); }
function assignChoice(choice: RosterChoice, id: string, teamId: TeamId) { if (choice.record) return careerRecordToDefinition(choice.record, id, teamId); if (choice.officialId) return officialProfileToDefinition(OFFICIAL_ROSTER_BY_ID[choice.officialId], id, teamId); const fixture = WRESTLERS[choice.fixtureId!]; return { ...structuredClone(fixture), id, teamId, sourceRecordId: fixture.id }; }
function rosterChoiceSummary(choice: RosterChoice): string { if (choice.officialId) { const profile = OFFICIAL_ROSTER_BY_ID[choice.officialId]; return `${profile.side === "fan-favorite" ? "Fan Favorite" : "Rulebreaker"} · AV ${profile.printedAv} · DV ${profile.printedDv} · END ${profile.attributes.end} · POW ${profile.attributes.pow} · TEC ${profile.attributes.tec} · ${profile.weight} lb${profile.tagTeam ? ` · ${profile.tagTeam.name}` : ""}`; } if (choice.record) return `${choice.record.side === "fan-favorite" ? "Fan Favorite" : "Rulebreaker"} · ${choice.record.careerWp} WP · AV ${baseAv(choice.record.attributes)} · DV ${baseDv(choice.record.attributes)} · ${choice.record.weight} lb`; const fixture = WRESTLERS[choice.fixtureId!]; return `Test fixture · ${fixture.side === "fan-favorite" ? "Fan Favorite" : "Rulebreaker"} · AV ${baseAv(fixture.attributes)} · DV ${baseDv(fixture.attributes)}`; }

