  if (!campaign) return <section className="m4-surface career-surface" aria-labelledby="career-title"><div className="surface-heading"><div><div className="prototype-tag">CAREER</div><h2 id="career-title">Start or continue a career</h2><p>Build a wrestler over time, play scheduled matches against the AI, and carry results, rankings, titles, injuries and progression forward.</p></div></div><div className="creator-grid"><section className="form-card"><h3>New career</h3><section aria-label="Rules compatibility"><h4>Rules compatibility</h4><label className="finance-toggle"><input type="checkbox" aria-label="Strict Manual Mode" checked={strictManualSetup} onChange={(event) => setStrictManualEnabled(event.target.checked)} /> Strict Manual Mode</label><p aria-live="polite">{strictManualSetup ? "Strict Manual Mode is selected. Adjudicated gameplay extensions are disabled for this new career; AI difficulty still changes legal action selection only." : "Extensions may be enabled in Career setup. The resulting campaign will report every setting outside Strict Manual compatibility."}</p><small>Compatibility is derived from campaign settings; no strict-manual save flag is stored.</small></section><label>Career name<input aria-label="Career name" value={careerName} onChange={(event) => setCareerName(event.target.value)} /></label><label>Career type<select aria-label="Career type" value={division} onChange={(event) => { setDivision(event.target.value as CampaignDivision); setCareerPlayerEntrantId(""); }}><option value="singles">Solo wrestler</option><option value="tag">Persistent team</option></select></label><label>AI difficulty<select aria-label="Career AI difficulty" aria-describedby="career-difficulty-hint" value={careerAiDifficulty} onChange={(event) => setCareerAiDifficulty(event.target.value as AiDifficulty)}>{AI_DIFFICULTIES.map((difficulty) => <option key={difficulty} value={difficulty}>{difficulty[0].toUpperCase()}{difficulty.slice(1)}</option>)}</select></label><DifficultyHint id="career-difficulty-hint" difficulty={careerAiDifficulty} />{setupRecords.length >= 4 && division === "singles" && <label>Your wrestler<select aria-label="Career player wrestler" value={careerPlayerEntrantId} onChange={(event) => setCareerPlayerEntrantId(event.target.value)}><option value="">Choose automatically</option>{setupRecords.map((record) => <option key={record.id} value={record.id}>{record.name} ({record.careerWp} WP)</option>)}</select></label>}{setupRecords.length >= 4 && division === "tag" && <label>Your team<select aria-label="Career player team" value={careerPlayerEntrantId} onChange={(event) => setCareerPlayerEntrantId(event.target.value)}><option value="">Choose automatically</option>{setupTeams.map((team) => <option key={team.id} value={team.id}>{team.name}</option>)}</select></label>}<p className="form-card__note">{setupRecords.length} created/imported Career record{setupRecords.length === 1 ? " is" : "s are"} available. The 1991 printed source profiles are available in Exhibition; Career records retain creation/progression history, so source profiles are not converted into fabricated creation histories.</p><div className="button-row"><button disabled={setupRecords.length < 4} onClick={() => start(false, false)}>Start from my roster</button><button className="button--quiet" onClick={() => start(true, false)}>Start generated starter league</button></div><details className="difficulty-hint-disclosure"><summary>Advanced / optional extensions</summary><label>Vacancy resolution<select aria-label="Vacancy resolution" value={vacancyMethod} onChange={(event) => setVacancyMethod(event.target.value as "ranked-contenders" | "tournament")}><option value="ranked-contenders">Top two ranked contenders</option><option value="tournament">Four-seed tournament</option></select></label><label>Post-match injury checks<select aria-label="Post-match injury checks" value={strictManualSetup ? "off" : postMatchInjury} disabled={strictManualSetup} onChange={(event) => setPostMatchInjury(event.target.value as "off" | "d20-check")}><option value="off">Core chart injuries only</option><option value="d20-check">Extended post-match D20 check</option></select></label><p className="form-card__note">The options below are later Ringcraft extensions, not part of the 1991 core rules.</p><label className="finance-toggle"><input type="checkbox" aria-label="Enable contracts and finance extension" checked={financeEnabled} disabled={strictManualSetup} onChange={(event) => { setFinanceEnabled(event.target.checked); if (!event.target.checked) { setNegotiationEnabled(false); setRenewalEnabled(false); } }} /> Contracts and finance</label><label className="finance-toggle"><input type="checkbox" aria-label="Enable contract negotiation extension" checked={negotiationEnabled} disabled={strictManualSetup || !financeEnabled} onChange={(event) => { setNegotiationEnabled(event.target.checked); if (!event.target.checked) setRenewalEnabled(false); }} /> Contract negotiation</label><label className="finance-toggle"><input type="checkbox" aria-label="Enable curve-fair renewals" checked={renewalEnabled} disabled={strictManualSetup || !negotiationEnabled} onChange={(event) => setRenewalEnabled(event.target.checked)} /> Curve-fair renewals</label><label className="finance-toggle"><input type="checkbox" aria-label="Enable feuds and booking extension" checked={bookingEnabled} disabled={strictManualSetup} onChange={(event) => setBookingEnabled(event.target.checked)} /> Feuds and booking</label></details><details className="difficulty-hint-disclosure"><summary>Developer / deterministic options</summary><label>Manual seed<input aria-label="Career seed" value={careerSeed} onChange={(event) => setCareerSeed(event.target.value)} /></label><button className="button--quiet" disabled={setupRecords.length < 4} onClick={() => start(false, true)}>Start my roster with manual seed</button><button className="button--quiet" onClick={() => start(true, true)}>Start generated league with manual seed</button></details></section><section className="form-card"><h3>Continue or import</h3><SaveManagerPanel saves={saves} canSave={false} saveName={saveName} onSaveNameChange={setSaveName} onSave={saveCurrentCampaign} onLoad={loadSave} onDuplicate={duplicateSaveRow} onRename={renameSaveRow} onDelete={deleteSaveRow} onOverwrite={overwriteSaveRow} onExportBundle={exportSaveBundleFile} onImportBundleFile={importSaveBundleFile} remoteEndpoint={remoteEndpoint} remoteAuthToken={remoteAuthToken} remoteAutoSync={remoteAutoSync} remoteBusy={remoteBusy} remoteStatus={remoteStatus} remoteError={remoteError} lastSynced={lastSynced} onRemoteEndpointChange={updateRemoteEndpoint} onRemoteAuthTokenChange={updateRemoteAuthToken} onRemoteAutoSyncChange={updateRemoteAutoSync} onRemoteSync={() => void runRemoteSync("sync")} onRemoteForcePush={() => void runRemoteSync("forcePush")} onRemoteForcePull={() => void runRemoteSync("forcePull")} /><label className="import-control">Import campaign JSON<input aria-label="Import campaign JSON" type="file" accept="application/json,.json" onChange={(event) => void importFile(event.target.files?.[0])} /></label><label className="import-control">Import Career roster<input aria-label="Import reference roster JSON" type="file" accept="application/json,.json" onChange={(event) => void importRosterFile(event.target.files?.[0])} /></label>{message && <pre className="validation" aria-live="polite">{message}</pre>}{bundleImportPreview}</section><section className="form-card"><h3>Before you start</h3><p>Create wrestlers in the Creator, import validated Career records, or use the generated starter league for immediate solo play.</p><p>The game autosaves every accepted Career transaction; named saves and JSON export remain available as additional recovery points.</p><details className="difficulty-hint-disclosure"><summary>Developer fixtures</summary><p>Read-only fixtures are retained for regression and recovery testing.</p><div className="button-row"><button className="button--quiet" onClick={() => loadPlaytestFixture(loadCompletedM5Fixture)}>Load completed fixture</button><button className="button--quiet" onClick={() => loadPlaytestFixture(loadInProgressM5Fixture)}>Load in-progress fixture</button></div></details></section></div></section>;
